const interior=document.createElement('section');interior.className='study-interior';interior.setAttribute('aria-label','별빛 스터디 카페 공간');interior.innerHTML=`<div class="interior-heading"><div><span class="eyebrow">STARLIGHT LIBRARY & LOUNGE</span><h2>어서 와요, 오늘은 어디에 앉을까요?</h2><p>공부할 공간을 고르면 아래에서 오늘의 목표를 정할 수 있어요.</p></div><span id="myRoomState" class="room-state">자리를 골라 주세요</span></div><div class="cafe-floor"><section class="library-zone"><div class="zone-heading"><span>01 · 조용한 도서관</span><small>책장 사이, 차분하게 집중</small></div><div class="shelf-wall" aria-hidden="true">${Array.from({length:3},()=>'<div class="bookcase">'+Array.from({length:13},(_,i)=>'<i style="--book:'+['#9a6e57','#73886c','#c6ae79','#667f8c','#ad847e'][i%5]+';--height:'+(22+i%4*5)+'px"></i>').join('')+'</div>').join('')}</div><div class="reading-tables">${[0,1,2].map(i=>`<button class="reading-desk seat-choice" data-seat="도서관" aria-label="도서관 책상 선택"><span class="table-lamp" aria-hidden="true"></span><span class="open-book" aria-hidden="true"></span><span class="pencil" aria-hidden="true"></span><span class="desk-chair" aria-hidden="true"></span><span class="desk-caption">도서관 책상</span></button>`).join('')}</div><div id="libraryPeople" class="room-people"></div></section><section class="window-zone"><div class="zone-heading"><span>02 · 달빛 창가</span><small>내 속도로, 창밖을 바라보며</small></div><div class="cafe-windows" aria-hidden="true"><span>✦</span><span>☾</span><span>✧</span></div><div class="window-desks">${[0,1].map(i=>'<button class="window-desk seat-choice" data-seat="창가" aria-label="창가 책상 선택"><span class="table-lamp" aria-hidden="true"></span><span class="open-book" aria-hidden="true"></span><span class="desk-chair" aria-hidden="true"></span><span class="desk-caption">창가 책상</span></button>').join('')}</div><div id="windowPeople" class="room-people"></div></section><div class="cafe-walkway"><span>🌿</span><span>책상에서 집중하고, 라운지에서 잠깐 쉬어요</span><span>🌿</span></div><section class="fire-zone"><div class="zone-heading"><span>03 · 모닥불 서재</span><small>따뜻한 조명 아래 책 한 권</small></div><div class="fireside-furniture"><div class="fireplace" aria-hidden="true"><span>♨</span></div><button class="fireside-desk seat-choice" data-seat="모닥불" aria-label="모닥불 서재 선택"><span class="open-book" aria-hidden="true"></span><span class="desk-caption">서재 자리</span></button></div><div id="firePeople" class="room-people"></div></section><section class="lounge-zone"><div class="zone-heading"><span>☕ 쉬어 가는 라운지</span><small>쉬는 동안 집중 시간은 멈춰요</small></div><div class="lounge-furniture" aria-hidden="true"><div class="sofa sofa-left"><i></i><i></i></div><div class="coffee-table"><span>☕</span><span>🌱</span></div><div class="sofa sofa-right"><i></i><i></i></div><div class="lounge-rug"></div></div><div id="loungePeople" class="room-people"></div><button id="loungeAction" class="lounge-action">라운지에서 잠깐 쉬기</button></section></div><p class="interior-caption">책상은 함께 사용하는 공간을 나타내요. 친구들의 별명은 실제 접속 상태에 따라 표시됩니다.</p>`;
$('.study-hero').after(interior);let loungePreview=false;
const baseInteriorDisplay=display;display=function(d){baseInteriorDisplay(d);drawInterior()};
function drawInterior(){if(!data)return;const s=data.current,selected=s?.seat||$('#studySeat').value;interior.querySelectorAll('[data-seat]').forEach(b=>{const active=b.dataset.seat===selected&&!loungePreview;b.classList.toggle('chosen',active);b.setAttribute('aria-pressed',String(active));b.disabled=false});$('#myRoomState').textContent=s?(s.status==='active'?s.seat+'에서 집중 중':'라운지에서 쉬는 중'):loungePreview?'라운지 둘러보는 중':selected+' 선택됨';interior.classList.toggle('in-lounge',!!s&&s.status==='paused'||loungePreview);$('#loungeAction').textContent=s?(s.status==='active'?'☕ 라운지로 이동 · 집중 잠시 멈춤':'📖 '+s.seat+'로 돌아가 집중하기'):loungePreview?'📖 공부 자리로 돌아가기':'☕ 라운지 둘러보기';$('#loungeAction').disabled=!!s&&s.status==='paused'&&(!data.library||data.paused);const groups={libraryPeople:[],windowPeople:[],firePeople:[],loungePeople:[]};for(const person of data.peers){const key=person.status==='쉬는 중'?'loungePeople':person.seat==='도서관'?'libraryPeople':person.seat==='모닥불'?'firePeople':'windowPeople';groups[key].push(person)}renderSeatedFriends(groups)}

interior.addEventListener('click',e=>{const button=e.target.closest('[data-seat]');if(!button)return;if(data?.current){message('현재 '+data.current.seat+'에서 공부 중이에요. 마무리 후 다음 공간을 고를 수 있어요.');return}loungePreview=false;$('#studySeat').value=button.dataset.seat;drawInterior();message(button.dataset.seat+'를 골랐어요. 오늘 할 일을 적고 공부를 시작해 보세요.');$('.focus-card').scrollIntoView({behavior:'smooth',block:'center'});$('#studyGoal').focus({preventScroll:true})});
$('#studySeat').addEventListener('change',()=>{loungePreview=false;drawInterior()});$('#loungeAction').onclick=async()=>{if(busy)return;if(!data?.current){loungePreview=!loungePreview;drawInterior();message(loungePreview?'라운지에서 쉬어 가세요. 아직 집중 시간은 시작하지 않았어요.':'다시 책상으로 돌아왔어요. 목표를 적고 시작해 주세요.');return}const action=data.current.status==='active'?'pause':'resume',result=await act('/api/campus/study',{action,id:data.current.id});if(result){loungePreview=false;drawInterior();message(action==='pause'?'라운지에 왔어요. 쉬는 동안 집중 시간은 멈춰 있어요.':'내 책상으로 돌아왔어요. 다시 함께 집중해요.')}};

const seatedNodes=new Map(),roomPages={},movingFriends=new Map();
for(const [zone,seat]of [['library','도서관'],['window','창가'],['fire','모닥불']]){const choice=document.createElement('button');choice.className='room-select';choice.dataset.seat=seat;choice.textContent='이 공간 선택';choice.setAttribute('aria-label',seat+' 공간 선택');interior.querySelector('.'+zone+'-zone .zone-heading').append(choice)}
let reduceCafeMotion=false;try{reduceCafeMotion=JSON.parse(localStorage.getItem('ieum-preferences')||'{}').ambient===false}catch{}
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
const motionLabel=document.createElement('label');motionLabel.className='cafe-motion';motionLabel.innerHTML='<input type="checkbox" id="cafeMotion"> 캐릭터 움직임 줄이기';interior.querySelector('.interior-heading').append(motionLabel);$('#cafeMotion').checked=reduceCafeMotion||motionPreference.matches;
function applyCafeMotion(){interior.classList.toggle('still-cafe',$('#cafeMotion').checked||motionPreference.matches);if(interior.classList.contains('still-cafe'))for(const stop of movingFriends.values())stop()}
$('#cafeMotion').onchange=()=>{let prefs={};try{prefs=JSON.parse(localStorage.getItem('ieum-preferences')||'{}')}catch{}prefs.ambient=!$('#cafeMotion').checked;localStorage.setItem('ieum-preferences',JSON.stringify(prefs));applyCafeMotion()};motionPreference.addEventListener('change',applyCafeMotion);applyCafeMotion();
function avatarMarkup(){return '<span class="seated-avatar" aria-hidden="true"><i class="avatar-head"></i><i class="avatar-body"></i><i class="avatar-arm arm-left"></i><i class="avatar-arm arm-right"></i><i class="avatar-leg leg-left"></i><i class="avatar-leg leg-right"></i></span>'}
function renderSeatedFriends(groups){const oldPositions=new Map();for(const [id,node]of seatedNodes){const avatar=node.querySelector('.seated-avatar');if(node.isConnected&&avatar.getClientRects().length)oldPositions.set(id,{rect:avatar.getBoundingClientRect(),group:node.dataset.group})}
const alive=new Set(data.peers.map(p=>p.id));for(const [id,node]of seatedNodes)if(!alive.has(id)){movingFriends.get(id)?.();node.remove();seatedNodes.delete(id)}
for(const [group,people]of Object.entries(groups)){const host=$('#'+group),page=Math.min(roomPages[group]||0,Math.max(0,Math.ceil(people.length/6)-1));roomPages[group]=page;const shown=people.slice(page*6,page*6+6),resting=group==='loungePeople';host.replaceChildren();host.classList.toggle('seated-room',!!people.length);host.parentElement.classList.toggle('has-seated-friends',!!people.length);
if(!people.length){host.innerHTML='<span class="room-empty">'+(resting?'소파에서 쉬어 갈 자리가 있어요':'책상에서 함께 공부할 친구를 기다려요')+'</span>';continue}
for(const person of shown){let station=seatedNodes.get(person.id);if(!station){station=document.createElement('div');station.className='friend-station';station.dataset.peer=person.id;station.innerHTML='<span class="seat-back" aria-hidden="true"></span>'+avatarMarkup()+'<span class="personal-desk" aria-hidden="true"><i class="personal-lamp"></i><i class="personal-book"></i><i class="tea-cup">☕</i></span><span class="friend-name"></span><small class="friend-class"></small>';seatedNodes.set(person.id,station)}
station.dataset.group=group;station.dataset.pose=resting?'resting':'reading';station.classList.toggle('resting',resting);station.style.setProperty('--shirt',['#88adc2','#d6a36d','#9daf87','#b899bb'][Array.from(person.id).reduce((n,c)=>n+c.charCodeAt(0),0)%4]);station.querySelector('.friend-name').textContent=person.name;station.querySelector('.friend-class').textContent=(data.rooms.find(r=>r.id===person.room)?.label||'우리 반')+' · '+person.status;station.setAttribute('aria-label',person.name+' · '+(resting?'소파에 앉아 쉬는 중':person.seat+' 책상에 앉아 책을 읽는 중'));host.append(station);
const old=oldPositions.get(person.id);if(old&&old.group!==group&&!interior.classList.contains('still-cafe')&&!document.hidden){const avatar=station.querySelector('.seated-avatar'),next=avatar.getBoundingClientRect();if(old.rect.width&&next.width)walkToSeat(person.id,avatar,old.rect,next)}}
const pager=document.createElement('div');pager.className='seat-pagination';pager.innerHTML=`<span>${page*6+1}–${Math.min((page+1)*6,people.length)} / ${people.length}명</span>${people.length>6?`<button data-seat-page="${group}" data-step="-1" ${page===0?'disabled':''} aria-label="이전 친구들">←</button><button data-seat-page="${group}" data-step="1" ${(page+1)*6>=people.length?'disabled':''} aria-label="다음 친구들">→</button>`:''}`;host.append(pager)}
}
function walkToSeat(id,avatar,from,to){movingFriends.get(id)?.();const ghost=avatar.cloneNode(true);ghost.classList.add('walking-friend');ghost.style.setProperty('--shirt',avatar.parentElement.style.getPropertyValue('--shirt'));Object.assign(ghost.style,{position:'fixed',left:from.left+'px',top:from.top+'px',width:from.width+'px',height:from.height+'px',zIndex:'1000'});document.body.append(ghost);avatar.style.visibility='hidden';const dx=to.left-from.left,dy=to.top-from.top;let finished=false;const cleanup=()=>{if(finished)return;finished=true;animation.cancel();ghost.remove();avatar.style.visibility='';movingFriends.delete(id)};const animation=ghost.animate([{transform:'translate(0,0)'},{transform:`translate(0,${dy*.5}px)`,offset:.3},{transform:`translate(${dx}px,${dy*.5}px)`,offset:.7},{transform:`translate(${dx}px,${dy}px)`}],{duration:1400,easing:'ease-in-out'});movingFriends.set(id,cleanup);animation.onfinish=cleanup;}
interior.addEventListener('click',e=>{const b=e.target.closest('[data-seat-page]');if(!b)return;roomPages[b.dataset.seatPage]=(roomPages[b.dataset.seatPage]||0)+Number(b.dataset.step);drawInterior()});
interior.querySelector('.interior-caption').textContent='실제 접속한 친구들이 책상과 소파에 앉아 있어요. 공간마다 6명씩 볼 수 있으며, 친구 상태는 약 15초마다 반영돼요.';
if(data)drawInterior();
